<?php
declare(strict_types=1);

function platform_admin(): ?array { return $_SESSION['platform_admin']??null; }
function require_platform_admin(): void { if(!platform_admin())redirect('/platform/login'); }
function platform_start(string $title): void { $admin=platform_admin();ob_start(fn(string $html):string=>base_path()===''?$html:preg_replace('/\\b(href|src|action)="\\/(?!\\/)/','$1="'.base_path().'/', $html));?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=e($title)?> · Amplificati</title><link rel="stylesheet" href="/assets/app.css"><style>:root{--brand:#4f2d7f;--accent:#19a974}</style></head><body><div class="shell"><aside class="sidebar"><div class="brand"><strong>Amplificati</strong></div><nav class="nav"><a class="active" href="/platform">Empresas</a><a href="/platform/password">Minha senha</a><a href="/platform/logout">Sair</a></nav></aside><main><div class="topbar"><div class="topbar-title"><button class="menu-toggle" type="button" data-menu-toggle><span></span><span></span><span></span></button><div><h1><?=e($title)?></h1><span class="muted"><?=e($admin['name']??'')?> · Administração da plataforma</span></div></div></div>
<?php $flash=$_SESSION['flash']??null;unset($_SESSION['flash']);if($flash):?><div class="alert <?=$flash[0]==='error'?'error':''?>"><?=e($flash[1])?></div><?php endif; }
function platform_end(): void { ?><div id="confirm-modal" class="modal-backdrop"><div class="modal"><h3>Confirmar ação</h3><p data-message></p><div class="actions"><button class="btn" data-yes>Sim, confirmar</button><button class="btn secondary" data-no>Cancelar</button></div></div></div><script>window.APP_BASE=<?=json_encode(base_path(),JSON_UNESCAPED_SLASHES)?>;</script><script src="/assets/app.js"></script></main></div></body></html><?php ob_end_flush(); }

if($path==='/platform/login'){
 if(platform_admin())redirect('/platform');$error='';$captchaKey=config('captcha.site_key');
 if($method==='POST'){verify_csrf();if(!verify_captcha($_POST['cf-turnstile-response']??''))$error='Confirme o CAPTCHA.';else{$email=strtolower(trim($_POST['email']??''));$admin=query('SELECT * FROM platform_admins WHERE email=? AND active=1 LIMIT 1',[$email])->fetch();if($admin&&password_verify($_POST['password']??'',$admin['password_hash'])){session_regenerate_id(true);$_SESSION['platform_admin']=array_intersect_key($admin,array_flip(['id','name','email','must_change_password']));query('UPDATE platform_admins SET last_login_at=NOW() WHERE id=?',[$admin['id']]);redirect($admin['must_change_password']?'/platform/password':'/platform');}$error='E-mail ou senha inválidos.';}}
 ob_start(fn(string $html):string=>base_path()===''?$html:preg_replace('/\\b(href|src|action)="\\/(?!\\/)/','$1="'.base_path().'/', $html));?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="/assets/app.css"><?php if($captchaKey):?><script src="https://challenges.cloudflare.com/turnstile/v0/api.js" async defer></script><?php endif?><title>Gestão Amplificati</title></head><body><div class="login"><form class="card" method="post"><h1>Gestão Amplificati</h1><p class="muted">Área exclusiva para administração das empresas.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><input type="hidden" name="_token" value="<?=csrf()?>"><div class="field"><label>E-mail</label><input type="email" name="email" required autocomplete="username"></div><br><div class="field"><label>Senha</label><input type="password" name="password" required autocomplete="current-password"></div><br><?php if($captchaKey):?><div class="cf-turnstile" data-sitekey="<?=e($captchaKey)?>"></div><br><?php endif?><button class="btn" style="width:100%">Entrar</button><br><br><a href="/login">Voltar ao login das empresas</a></form></div></body></html><?php ob_end_flush();exit;
}
if($path==='/platform/logout'){unset($_SESSION['platform_admin']);redirect('/platform/login');}
if(!str_starts_with($path,'/platform'))return;
require_platform_admin();
if(!empty(platform_admin()['must_change_password'])&&$path!=='/platform/password')redirect('/platform/password');

if($path==='/platform/password'){
 if($method==='POST'){verify_csrf();$password=(string)($_POST['password']??'');if(strlen($password)<12||$password!==($_POST['password_confirmation']??'')){flash('error','Use pelo menos 12 caracteres e confirme a mesma senha.');redirect('/platform/password');}query('UPDATE platform_admins SET password_hash=?,must_change_password=0 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),platform_admin()['id']]);$_SESSION['platform_admin']['must_change_password']=0;flash('success','Senha alterada com segurança.');redirect('/platform');}
 platform_start('Minha senha');?><form class="card" method="post"><input type="hidden" name="_token" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Nova senha</label><input type="password" name="password" minlength="12" required></div><div class="field"><label>Confirmar nova senha</label><input type="password" name="password_confirmation" minlength="12" required></div></div><br><button class="btn" data-confirm="Confirmar a alteração da senha administrativa?">Alterar senha</button></form><?php platform_end();exit;
}
if($path==='/platform/companies/save'&&$method==='POST'){
 verify_csrf();$name=trim($_POST['name']??'');$slug=strtolower(trim($_POST['slug']??''));$slug=trim(preg_replace('/[^a-z0-9_-]+/','-',$slug),'-');$managerEmail=strtolower(trim($_POST['manager_email']??''));$password=(string)($_POST['manager_password']??'');
 if($name===''||$slug===''||!filter_var($managerEmail,FILTER_VALIDATE_EMAIL)||strlen($password)<10){flash('error','Preencha empresa, código, gestor e uma senha inicial de pelo menos 10 caracteres.');redirect('/platform');}
 db()->beginTransaction();try{query('INSERT INTO companies(name,slug,primary_color,accent_color) VALUES(?,?,?,?)',[$name,$slug,$_POST['primary_color']??'#173F73',$_POST['accent_color']??'#F3B61F']);$companyId=(int)db()->lastInsertId();query('INSERT INTO users(company_id,name,email,password_hash,role) VALUES(?,?,?,?,?)',[$companyId,trim($_POST['manager_name']),$managerEmail,password_hash($password,PASSWORD_DEFAULT),'manager']);foreach(['Em uso','Reserva','Em manutenção','Baixado'] as $status)query("INSERT INTO catalog_items(company_id,catalog_type,name) VALUES(?,'asset_status',?)",[$companyId,$status]);foreach(['Windows 10 Pro','Windows 11 Pro'] as $windows)query("INSERT INTO catalog_items(company_id,catalog_type,name) VALUES(?,'windows_version',?)",[$companyId,$windows]);db()->commit();flash('success','Empresa cadastrada. O código de acesso é '.$slug.'.');}catch(Throwable $error){db()->rollBack();flash('error','Não foi possível cadastrar. Verifique se o código ou e-mail já existe.');}redirect('/platform');
}
if($path==='/platform/companies/toggle'&&$method==='POST'){verify_csrf();query('UPDATE companies SET active=1-active WHERE id=?',[(int)$_POST['id']]);flash('success','Status da empresa atualizado.');redirect('/platform');}
if($path==='/platform'){
 $companies=query('SELECT c.*,COUNT(DISTINCT u.id) users_count,COUNT(DISTINCT pc.id) computers_count FROM companies c LEFT JOIN users u ON u.company_id=c.id LEFT JOIN computers pc ON pc.company_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();platform_start('Empresas');?><div class="grid kpis"><div class="card kpi"><strong><?=count($companies)?></strong><span>Empresas cadastradas</span></div><div class="card kpi"><strong><?=count(array_filter($companies,fn($c)=>(bool)$c['active']))?></strong><span>Contratos ativos</span></div><div class="card kpi"><strong><?=array_sum(array_column($companies,'computers_count'))?></strong><span>Computadores gerenciados</span></div></div><br><details class="card"><summary><strong>+ Cadastrar nova empresa</strong></summary><br><form method="post" action="/platform/companies/save"><input type="hidden" name="_token" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Nome da empresa</label><input name="name" required></div><div class="field"><label>Código usado no login</label><input name="slug" required placeholder="ex.: colegio-cave" pattern="[a-z0-9_-]+"></div><div class="field"><label>Cor principal</label><input type="color" name="primary_color" value="#173F73"></div><div class="field"><label>Cor de destaque</label><input type="color" name="accent_color" value="#F3B61F"></div><div class="full"><h3>Primeiro gestor da empresa</h3></div><div class="field"><label>Nome do gestor</label><input name="manager_name" required></div><div class="field"><label>E-mail do gestor</label><input type="email" name="manager_email" required></div><div class="field"><label>Senha inicial</label><input type="password" name="manager_password" minlength="10" required></div></div><br><button class="btn" data-confirm="Criar esta empresa e o primeiro gestor?">Cadastrar empresa</button></form></details><br><div class="card table-card"><div class="card-heading"><div><h3>Empresas da plataforma</h3><span>O código é informado pelos usuários na tela de login.</span></div></div><div class="table-wrap"><table data-table><thead><tr><th>Empresa</th><th>Código no login</th><th>Usuários</th><th>Computadores</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($companies as $company):?><tr><td><strong><?=e($company['name'])?></strong></td><td><code><?=e($company['slug'])?></code></td><td><?=e($company['users_count'])?></td><td><?=e($company['computers_count'])?></td><td><span class="badge <?=$company['active']?'ok':'critical'?>"><?=$company['active']?'Ativa':'Suspensa'?></span></td><td><form method="post" action="/platform/companies/toggle"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$company['id']?>"><button class="btn small <?=$company['active']?'danger':'secondary'?>" data-confirm="<?=$company['active']?'Suspender o acesso desta empresa?':'Reativar esta empresa?'?>"><?=$company['active']?'Suspender':'Reativar'?></button></form></td></tr><?php endforeach?></tbody></table></div></div><?php platform_end();exit;
}
